def to_xml(self, version: str, nsmap: Any=None, prettyprint: bool=True, indent: str='') ->Optional[str]:
    from . import gpx as mod_gpx
    from . import gpxfield as mod_gpxfield

    if nsmap is None:
        nsmap = {'defaultns': 'http://www.topografix.com/GPX/1/1'}
        if version == '1.0':
            nsmap['defaultns'] = 'http://www.topografix.com/GPX/1/0'

    # Handle schema locations
    schema_locations = []
    if hasattr(self, 'schema_locations') and self.schema_locations:
        schema_locations = self.schema_locations
    else:
        if version == '1.0':
            schema_locations = [
                'http://www.topografix.com/GPX/1/0',
                'http://www.topografix.com/GPX/1/0/gpx.xsd'
            ]
        else:  # version == '1.1'
            schema_locations = [
                'http://www.topografix.com/GPX/1/1',
                'http://www.topografix.com/GPX/1/1/gpx.xsd'
            ]

    # Build custom attributes
    custom_attributes = {}
    if hasattr(self, 'creator') and self.creator:
        custom_attributes['creator'] = self.creator

    # Generate XML
    result = gpx_fields_to_xml(self, 'gpx', version, custom_attributes, nsmap, prettyprint, indent)

    return result
